const CATEGORY_RULES = [
  { category: 'Pothole', keywords: ['pothole','pot hole','road damage','road crack','broken road','road hole','गड्ढा','सड़क में गड्ढा','टूटी सड़क','खराब सड़क','खड्डा','रस्त्यावर खड्डा','खड्डे','तुटलेला रस्ता','रस्त्यात खड्डा','मोठा खड्डा'], baseSeverity: 'HIGH', department: 'Roads & Public Works' },
  { category: 'Garbage', keywords: ['garbage','trash','waste','rubbish','litter','dump','solid waste','कचरा','कूड़ा','गंदगी','घाण','कचऱ्याचा ढीग','कचरा संकलन'], baseSeverity: 'MEDIUM', department: 'Sanitation' },
  { category: 'Water Leakage', keywords: ['water leakage','water leak','pipe leak','burst pipe','water pipe','pipeline','पानी की पाइप','पाइप लीक','पानी रिसाव','नल लीक','पाण्याची गळती','पाइप फुटला','पाणी गळत','नळ गळतो','पाणी गळती'], baseSeverity: 'HIGH', department: 'Water & Sewage' },
  { category: 'Drainage', keywords: ['drainage','drain','blocked drain','clogged drain','waterlogging','flooding','manhole','नाली','नाला','जलजमाव','नाली बंद','गटार','नाले','जलभराव','गटार बंद','मॅनहोल','तुंबलेले गटार'], baseSeverity: 'HIGH', department: 'Storm Water & Drainage' },
  { category: 'Broken Streetlight', keywords: ['streetlight','street light','light not working','lamp post','dark road','no light','स्ट्रीट लाइट','बत्ती नहीं','लाइट खराब','अँधेरा','दिवा','दिवे नाही','दिवा बंद','रस्त्यावर अंधार','स्ट्रीट लाईट'], baseSeverity: 'MEDIUM', department: 'Electrical / Street Lighting' },
  { category: 'Sewage', keywords: ['sewage','sewer','sewage overflow','manhole overflow','stench','smell','bad odor','सीवर','सीवेज','बदबू','सांडपाणी','दुर्गंधी','सांडपाणी भरले'], baseSeverity: 'HIGH', department: 'Water & Sewage' },
  { category: 'Road Damage', keywords: ['road damage','damaged road','road collapsed','road broken','सड़क टूट','रोड ब्रेकडाउन','रस्ता खराब','रस्ता तुटला'], baseSeverity: 'HIGH', department: 'Roads & Public Works' },
  { category: 'Tree Hazard', keywords: ['fallen tree','tree fallen','dead tree','dangerous tree','झाड गिरा','पेड़ गिरा','झाड पडले','झाड धोकादायक'], baseSeverity: 'HIGH', department: 'Parks & Horticulture' },
];
const MARATHI_MARKERS = ['आहे','नाही','आमच्या','परिसरात','रस्त्यावर','खड्डा','पाण्याची','गळती','गटार','दिवा','आमचा','करा','तुटला','झाले','होते'];
const HINDI_MARKERS   = ['है','नहीं','हमारे','सड़क','गड्ढा','नाली','हैं','करें','किया','रहा','था'];
const URGENCY_HIGH    = ['urgent','emergency','dangerous','critical','immediately','accident','injury','खतरनाक','तातडीने','मोठा','भयंकर','धोकादायक'];
const ESCALATION      = { LOW:'MEDIUM', MEDIUM:'HIGH', HIGH:'CRITICAL', CRITICAL:'CRITICAL' };
function detectLanguage(text) {
  const devanagari = /[ऀ-ॿ]/.test(text);
  if (!devanagari) return { language: 'English', confidence: 0.95 };
  const mScore = MARATHI_MARKERS.filter(w => text.includes(w)).length;
  const hScore = HINDI_MARKERS.filter(w => text.includes(w)).length;
  if (mScore >= hScore) return { language: 'Marathi', confidence: Math.min(0.6 + mScore * 0.08, 0.97) };
  return { language: 'Hindi', confidence: Math.min(0.6 + hScore * 0.08, 0.97) };
}
function classify(text) {
  const lower = text.toLowerCase();
  let best = { category:'General Complaint', score:0, baseSeverity:'MEDIUM', department:'Municipal Corporation' };
  for (const rule of CATEGORY_RULES) {
    let score = 0;
    for (const kw of rule.keywords) {
      if (lower.includes(kw.toLowerCase()) || text.includes(kw)) score += kw.split(' ').length * 2 + 1;
    }
    if (score > best.score) best = { category: rule.category, score, baseSeverity: rule.baseSeverity, department: rule.department };
  }
  const confidence = best.score === 0 ? 0.40 : Math.min(0.55 + best.score * 0.04, 0.97);
  let severity = best.baseSeverity;
  if (URGENCY_HIGH.some(w => lower.includes(w.toLowerCase()) || text.includes(w))) severity = ESCALATION[severity] || severity;
  return { category: best.category, confidence: Math.round(confidence * 100), severity, department: best.department };
}
function generateTrackingId(ts) {
  const year = new Date(ts).getFullYear();
  return 'CIV-' + year + '-' + String(Math.floor(Math.random() * 90000) + 10000);
}
const items = $input.all();
return items.map(item => {
  const text = item.json.complaint_text || '';
  const lang = detectLanguage(text);
  const cls  = classify(text);
  const now  = new Date().toISOString();
  const severityEmoji = { LOW:'🟢', MEDIUM:'🟡', HIGH:'🔴', CRITICAL:'🚨' };
  const langFlag      = { English:'🇬🇧', Hindi:'🇮🇳', Marathi:'🇮🇳' };
  return {
    json: {
      reporter_name:   item.json.reporter_name  || 'Anonymous',
      reporter_phone:  item.json.reporter_phone || '',
      complaint_text:  text,
      location:        item.json.location || 'Not specified',
      language:        lang.language,
      lang_confidence: Math.round(lang.confidence * 100),
      lang_flag:       langFlag[lang.language] || '🌐',
      category:        cls.category,
      severity:        cls.severity,
      severity_emoji:  severityEmoji[cls.severity] || '🟡',
      department:      cls.department,
      confidence_pct:  cls.confidence,
      tracking_id:     generateTrackingId(now),
      status:          'PENDING',
      submitted_at:    now,
      is_duplicate:    false,
    }
  };
});

